SET @prov_c := ( SELECT provincecode FROM sys_config LIMIT 1 );
SET @b_year:=(SELECT yearprocess-1 FROM pk_byear LIMIT 1);
SET	@start_d:=concat(@b_year-1,'1001');

DROP TEMPORARY TABLE IF EXISTS tx;
CREATE TEMPORARY TABLE IF NOT EXISTS tx(
SELECT 
p.hospcode,p.PID,p.CID, p.NAME, p.LNAME, p.SEX, p.BIRTH, p.HID
,p.addr,p.check_vhid, p.NATION, p.check_typearea as typearea,p.discharge
,REPLACE(g_code,'},{','}<br>,{') g_code
,REPLACE(g_code_icd,'},{','}<br>,{') g_code_icd
,REPLACE(pharma_code,'},{','}<br>,{') pharma_code
FROM 	tmp_pallitive_kancha t  INNER JOIN  t_person_cid p ON t.cid=p.cid
INNER JOIN chospital h ON  p.check_hosp=h.hoscode 
WHERE p.NATION in(99) AND p.check_typearea IN(1,3)
);

SELECT 
h.hoscode, h.hosname,d.PID,d.CID, d.NAME, d.LNAME, d.SEX, d.BIRTH, d.HID
,d.addr,d.check_vhid, d.NATION, d.typearea,d.discharge
,d.g_code,d.g_code_icd,d.pharma_code
FROM
tx d
INNER JOIN chospital h ON d.hospcode = h.hoscode
WHERE 1=1 {where}
